class Solution {
public:
    std::vector<int> arraysIntersection(std::vector<int>& arr1, std::vector<int>& arr2, std::vector<int>& arr3) {
        int i = 0, j = 0, k = 0;
        int n1 = arr1.size(), n2 = arr2.size(), n3 = arr3.size();
        std::vector<int> res;
        while (i < n1 && j < n2 && k < n3) {
            int v1 = arr1[i], v2 = arr2[j], v3 = arr3[k];
            if (v1 == v2 && v2 == v3) {
                res.push_back(v1);
                i++; j++; k++;
            } else {
                int m = std::min({v1, v2, v3});
                if (v1 == m) i++;
                if (v2 == m) j++;
                if (v3 == m) k++;
            }
        }
        return res;
    }
};

class Solution {
    public java.util.List<Integer> arraysIntersection(int[] arr1, int[] arr2, int[] arr3) {
        int i = 0, j = 0, k = 0;
        int n1 = arr1.length, n2 = arr2.length, n3 = arr3.length;
        java.util.List<Integer> res = new java.util.ArrayList<>();
        while (i < n1 && j < n2 && k < n3) {
            int v1 = arr1[i], v2 = arr2[j], v3 = arr3[k];
            if (v1 == v2 && v2 == v3) {
                res.add(v1);
                i++; j++; k++;
            } else {
                int m = Math.min(v1, Math.min(v2, v3));
                if (v1 == m) i++;
                if (v2 == m) j++;
                if (v3 == m) k++;
            }
        }
        return res;
    }
}

